1	// This file implements organization-scoped policy publishing, rollback,
2	// and review on top of the decision core. Each organization versions its
3	// own policy set independently; all state is in-memory and lives until
4	// the service instance ends.
5	package darksafe
6	
7	import (
8		"errors"
9		"fmt"
10		"sort"
11		"strings"
12		"sync"
13	)
14	
15	// Effect is the outcome a policy produces when it matches a request.
16	type Effect string
17	
18	const (
19		EffectAllow Effect = "allow"
20		EffectDeny  Effect = "deny"
21	)
22	
23	// Policy binds one subject and one action to a scope with an effect.
24	type Policy struct {
25		ID        string
26		Subject   string
27		Action    string
28		Scope     string
29		Effect    Effect
30		Recursive bool // false: only the exact scope; true: the scope and its descendants
31		// ResourceID optionally narrows the policy to one exact resource. Empty
32		// keeps the legacy scope-only matching. A non-empty value adds a
33		// condition on top of subject, action, scope and the organization
34		// checks: it never replaces them. Comparison is against the request's
35		// raw resource ID, byte for byte: case sensitive, spaces significant,
36		// no wildcard or scope-path interpretation, and the resource needs no
37		// prior registration.
38		//
39		// The omitempty tag is load bearing for audit fingerprints: the legacy
40		// JSON fingerprint family never had this field, and an empty value must
41		// keep serializing to exactly the old bytes.
42		ResourceID string `json:",omitempty"`
43	}
44	
45	// Sentinel errors so callers can distinguish failure causes with errors.Is.
46	var (
47		// ErrVersionConflict means the caller's expected current version is stale.
48		ErrVersionConflict = errors.New("darksafe: version conflict")
49		// ErrVersionNotFound means the requested historical version does not exist.
50		ErrVersionNotFound = errors.New("darksafe: version not found")
51		// ErrInvalidPolicySet means the submitted policy set failed validation.
52		ErrInvalidPolicySet = errors.New("darksafe: invalid policy set")
53		// ErrMissingOrganization means an operation was called without an organization.
54		ErrMissingOrganization = errors.New("darksafe: organization is required")
55	)
56	
57	// OrgRequest is an access request evaluated against one organization's
58	// published policies. Both organizations must equal the decision organization.
59	type OrgRequest struct {
60		SubjectOrg  string
61		ResourceOrg string
62		Subject     Subject
63		Resource    Resource
64		Action      string
65	}
66	
67	// Store holds every organization's published policy versions. It is safe
68	// for concurrent use and keeps all state in memory.
69	type Store struct {
70		mu   sync.Mutex
71		orgs map[string]*orgState
72	}
73	
74	type orgState struct {
75		current  int              // 0 means nothing published yet
76		versions map[int][]Policy // immutable snapshots per version
77		audit    []*AuditRecord   // gapless, append-only audit chain
78	}
79	
80	// NewStore returns an empty Store.
81	func NewStore() *Store {
82		return &Store{orgs: make(map[string]*orgState)}
83	}
84	
85	func (s *Store) orgLocked(name string) *orgState {
86		st, ok := s.orgs[name]
87		if !ok {
88			st = &orgState{versions: make(map[int][]Policy)}
89			s.orgs[name] = st
90		}
91		return st
92	}
93	
94	// CurrentVersion reports the organization's current version, 0 if it has
95	// never published.
96	func (s *Store) CurrentVersion(org string) int {
97		s.mu.Lock()
98		defer s.mu.Unlock()
99		if st, ok := s.orgs[org]; ok {
100			return st.current
101		}
102		return 0
103	}
104	
105	// Publish validates and publishes a complete policy set as the next
106	// version. expectedVersion must equal the organization's current version;
107	// on any validation or version failure nothing changes and no version
108	// number is consumed.
109	func (s *Store) Publish(org string, expectedVersion int, policies []Policy) (int, error) {
110		if org == "" {
111			return 0, ErrMissingOrganization
112		}
113		snapshot, err := validatePolicies(policies)
114		if err != nil {
115			return 0, err
116		}
117		s.mu.Lock()
118		defer s.mu.Unlock()
119		st := s.orgLocked(org)
120		if expectedVersion != st.current {
121			return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
122		}
123		return st.commitVersionLocked(org, snapshot, 0, false), nil
124	}
125	
126	// Rollback republishes the full content of an existing historical version
127	// as a new version. History is never deleted or rewritten.
128	func (s *Store) Rollback(org string, expectedVersion, targetVersion int) (int, error) {
129		if org == "" {
130			return 0, ErrMissingOrganization
131		}
132		s.mu.Lock()
133		defer s.mu.Unlock()
134		st := s.orgLocked(org)
135		src, ok := st.versions[targetVersion]
136		if !ok {
137			return 0, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, targetVersion)
138		}
139		if expectedVersion != st.current {
140			return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
141		}
142		snapshot := append([]Policy(nil), src...)
143		return st.commitVersionLocked(org, snapshot, targetVersion, true), nil
144	}
145	
146	// commitVersionLocked advances the organization to the next version with
147	// the given policy snapshot and appends the matching policy-change record
148	// to the audit chain. It runs under the store mutex, so the new version
149	// and its audit record become visible together; callers must have already
150	// validated the input and checked the expected version, so a failed
151	// operation never reaches this point and leaves no record. A rollback
152	// passes its source version and rolledBack=true; an ordinary publish
153	// passes 0 and false.
154	func (st *orgState) commitVersionLocked(org string, snapshot []Policy, sourceVersion int, rolledBack bool) int {
155		st.current++
156		st.versions[st.current] = snapshot
157		st.appendAuditLocked(org, AuditPolicyChange, &PolicyChange{
158			Version:       st.current,
159			Policies:      snapshot,
160			SourceVersion: sourceVersion,
161			RolledBack:    rolledBack,
162		}, nil)
163		return st.current
164	}
165	
166	// Policies returns a copy of the full policy set of one version. Mutating
167	// the result does not affect published content.
168	func (s *Store) Policies(org string, version int) ([]Policy, error) {
169		s.mu.Lock()
170		defer s.mu.Unlock()
171		st, ok := s.orgs[org]
172		if !ok {
173			return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
174		}
175		src, ok := st.versions[version]
176		if !ok {
177			return nil, fmt.Errorf("%w: organization %q has no version %d", ErrVersionNotFound, org, version)
178		}
179		return append([]Policy(nil), src...), nil
180	}
181	
182	// Decide evaluates a request against the organization's current version.
183	// The whole decision uses that single version's snapshot, and the version
184	// actually used is reported in Decision.Version.
185	//
186	// Every call with a non-empty decision organization leaves a decision
187	// record, including envelope rejections (disabled subject, missing fields,
188	// organization mismatch) and the no-published-version denial. A call with
189	// an empty organization rejects as before and creates no record, because
190	// there is no organization to attribute it to. The evaluation and record
191	// append are atomic: a concurrent publish can never make the recorded
192	// version differ from the version that was evaluated.
193	func (s *Store) Decide(org string, req OrgRequest) Decision {
194		if org == "" {
195			d, _ := checkRequest(org, req)
196			return d
197		}
198		if d, ok := checkRequest(org, req); !ok {
199			s.mu.Lock()
200			st := s.orgLocked(org)
201			st.appendAuditLocked(org, AuditDecision, nil, &DecisionRecord{Request: req, Decision: d})
202			s.mu.Unlock()
203			return d
204		}
205		s.mu.Lock()
206		defer s.mu.Unlock()
207		st := s.orgLocked(org)
208		version := st.current
209		var d Decision
210		if version == 0 {
211			d = Decision{Allowed: false, Reason: "organization has no published version"}
212		} else {
213			d = evaluate(req, st.versions[version], version)
214		}
215		st.appendAuditLocked(org, AuditDecision, nil, &DecisionRecord{Request: req, Decision: d})
216		return d
217	}
218	
219	// Review re-evaluates a request against a specific historical version.
220	// Later publishes or rollbacks cannot change its outcome; a version that
221	// does not exist is a denial with a reason, never a silent fallback to
222	// the current version.
223	func (s *Store) Review(org string, version int, req OrgRequest) Decision {
224		if d, ok := checkRequest(org, req); !ok {
225			return d
226		}
227		s.mu.Lock()
228		var policies []Policy
229		found := false
230		if st, ok := s.orgs[org]; ok {
231			if src, ok := st.versions[version]; ok {
232				policies = append([]Policy(nil), src...)
233				found = true
234			}
235		}
236		s.mu.Unlock()
237		if !found {
238			return Decision{Allowed: false, Reason: fmt.Sprintf("version %d not found", version)}
239		}
240		return evaluate(req, policies, version)
241	}
242	
243	// checkRequest validates the request envelope. Every failure is a denial
244	// with a distinguishable reason.
245	func checkRequest(org string, req OrgRequest) (Decision, bool) {
246		switch {
247		case org == "":
248			return Decision{Allowed: false, Reason: "missing decision organization"}, false
249		case req.SubjectOrg == "":
250			return Decision{Allowed: false, Reason: "missing subject organization"}, false
251		case req.ResourceOrg == "":
252			return Decision{Allowed: false, Reason: "missing resource organization"}, false
253		case req.Subject.ID == "":
254			return Decision{Allowed: false, Reason: "missing subject id"}, false
255		case req.Resource.ID == "":
256			return Decision{Allowed: false, Reason: "missing resource id"}, false
257		case req.Action == "":
258			return Decision{Allowed: false, Reason: "missing action"}, false
259		}
260		if req.SubjectOrg != org || req.ResourceOrg != org {
261			return Decision{Allowed: false, Reason: "organization mismatch"}, false
262		}
263		if err := validateScope(req.Resource.Scope); err != nil {
264			return Decision{Allowed: false, Reason: "invalid scope: " + err.Error()}, false
265		}
266		if req.Subject.Disabled {
267			return Decision{Allowed: false, Reason: "subject is disabled"}, false
268		}
269		return Decision{}, true
270	}
271	
272	// evaluate applies one version's policies to a request. Subject roles are
273	// deliberately ignored: only the selected version's policies decide.
274	func evaluate(req OrgRequest, policies []Policy, version int) Decision {
275		seen := make(map[string]struct{})
276		denied := false
277		allowed := false
278		for _, p := range policies {
279			if p.Subject != req.Subject.ID || p.Action != req.Action {
280				continue
281			}
282			if !scopeMatches(p, req.Resource.Scope) {
283				continue
284			}
285			// A resource restriction is an additional condition, not a
286			// replacement for the scope check: even an equal ID cannot match a
287			// resource outside the policy's scope (including outside a
288			// recursive scope's subtree). The request envelope already
289			// rejected an empty resource ID, so an empty ResourceID here means
290			// "no restriction", never a match on a missing ID.
291			if p.ResourceID != "" && p.ResourceID != req.Resource.ID {
292				continue
293			}
294			seen[p.ID] = struct{}{}
295			switch p.Effect {
296			case EffectDeny:
297				denied = true
298			case EffectAllow:
299				allowed = true
300			}
301		}
302		matched := make([]string, 0, len(seen))
303		for id := range seen {
304			matched = append(matched, id)
305		}
306		sort.Strings(matched)
307		switch {
308		case denied:
309			return Decision{Allowed: false, Reason: "matched deny policy", Matched: matched, Version: version}
310		case allowed:
311			return Decision{Allowed: true, Reason: "matched allow policy", Matched: matched, Version: version}
312		default:
313			return Decision{Allowed: false, Reason: "no matching allow policy", Matched: matched, Version: version}
314		}
315	}
316	
317	// scopeMatches reports whether a policy's scope covers the request scope.
318	// Matching is by slash-separated segments, so "org/a" never covers "org/ab".
319	func scopeMatches(p Policy, scope string) bool {
320		if p.Scope == scope {
321			return true
322		}
323		return p.Recursive && strings.HasPrefix(scope, p.Scope+"/")
324	}
325	
326	// validatePolicies checks a submitted policy set and returns a detached
327	// copy, so later caller mutations cannot affect published content.
328	func validatePolicies(policies []Policy) ([]Policy, error) {
329		seen := make(map[string]struct{}, len(policies))
330		out := make([]Policy, len(policies))
331		for i, p := range policies {
332			if p.ID == "" {
333				return nil, fmt.Errorf("%w: policy at index %d has an empty id", ErrInvalidPolicySet, i)
334			}
335			if _, dup := seen[p.ID]; dup {
336				return nil, fmt.Errorf("%w: duplicate policy id %q", ErrInvalidPolicySet, p.ID)
337			}
338			seen[p.ID] = struct{}{}
339			if p.Subject == "" {
340				return nil, fmt.Errorf("%w: policy %q is missing a subject", ErrInvalidPolicySet, p.ID)
341			}
342			if p.Action == "" {
343				return nil, fmt.Errorf("%w: policy %q is missing an action", ErrInvalidPolicySet, p.ID)
344			}
345			if p.Effect != EffectAllow && p.Effect != EffectDeny {
346				return nil, fmt.Errorf("%w: policy %q has unknown effect %q", ErrInvalidPolicySet, p.ID, p.Effect)
347			}
348			if err := validateScope(p.Scope); err != nil {
349				return nil, fmt.Errorf("%w: policy %q has invalid scope: %v", ErrInvalidPolicySet, p.ID, err)
350			}
351			out[i] = p
352		}
353		return out, nil
354	}
355	
356	// validateScope rejects empty paths, leading/trailing slashes, consecutive
357	// slashes, and "." or ".." segments.
358	func validateScope(scope string) error {
359		if scope == "" {
360			return errors.New("scope is empty")
361		}
362		if strings.HasPrefix(scope, "/") || strings.HasSuffix(scope, "/") {
363			return fmt.Errorf("scope %q has a leading or trailing slash", scope)
364		}
365		for _, seg := range strings.Split(scope, "/") {
366			if seg == "" {
367				return fmt.Errorf("scope %q contains consecutive slashes", scope)
368			}
369			if seg == "." || seg == ".." {
370				return fmt.Errorf("scope %q contains invalid segment %q", scope, seg)
371			}
372		}
373		return nil
374	}
375

