74		if err != nil {
75			t.Fatalf("offline review deny: %v", err)
76		}
77		if !denied.Consistent || !reflect.DeepEqual(denied.Original, origDeny) {
78			t.Fatalf("deny review = %+v, want consistent with %+v", denied, origDeny)
79		}
80		if denied.Recomputed.Allowed || denied.Recomputed.Reason != "no matching allow policy" {
81			t.Fatalf("recomputed deny = %+v", denied.Recomputed)
