471			t.Fatalf("deny-overrides review = %+v, original %+v", got, original)
472		}
473		if got.Recomputed.Allowed || !reflect.DeepEqual(got.Recomputed.Matched, []string{"a-deny", "m-allow", "z-allow"}) {
474			t.Fatalf("recomputed = %+v", got.Recomputed)
475		}
476	}
