478	func TestOfflineReviewAcrossOrganizationsIndependent(t *testing.T) {
479		s := NewStore()
480		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
481		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
482		s.Publish("globex", 0, nil)
