562	// offlineForgedAllowChain builds a chain-valid export: version 1 carries a
563	// fully matching allow policy (optionally resource-restricted), and the
564	// target decision names version 1 and claims to be allowed by it.
565	func offlineForgedAllowChain(t *testing.T, org string, req OrgRequest, resourceID string) ([]AuditRecord, Checkpoint) {
566		t.Helper()
567		p := Policy{ID: "p1", Subject: req.Subject.ID, Action: req.Action, Scope: "org/a", Effect: EffectAllow, ResourceID: resourceID}
568		return syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
569			func(seq int) (string, *PolicyChange, *DecisionRecord) {
570				return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{p}}, nil
571			},
572			func(seq int) (string, *PolicyChange, *DecisionRecord) {
573				return AuditDecision, nil, &DecisionRecord{
574					Request:  req,
575					Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
576				}
577			},
578		})
579	}
