724				t.Fatalf("case %d recomputed = %+v, want online envelope decision %+v", i, got.Recomputed, online)
725			}
726			if got.Recomputed.Reason != tc.reason {
727				t.Fatalf("case %d reason = %q, want %q", i, got.Recomputed.Reason, tc.reason)
728			}
