// This file implements the organization-scoped audit chain. Every successful
// policy publish or rollback, and every Decide called with a non-empty
// decision organization, leaves an immutable record in that organization.
//
// Records carry an organization-local sequence starting at 1 and a SHA-256
// fingerprint that chains each record to the previous one. The genesis
// fingerprint binds the organization name, so records from another
// organization can never validate as part of this chain even when the
// sequence numbers and identifiers coincide.
package darksafe

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
)

// Audit record categories.
const (
	// AuditPolicyChange is a successful publish or rollback.
	AuditPolicyChange = "policy_change"
	// AuditDecision is one Decide evaluation.
	AuditDecision = "decision"
)

// Sentinel errors for the audit entry points. Callers distinguish them
// with errors.Is; every one leaves state unchanged.
var (
	// ErrInvalidPage means a page size or range argument was invalid.
	ErrInvalidPage = errors.New("darksafe: invalid audit page")
	// ErrInvalidRange means the upper bound is beyond what exists, the
	// range is inverted, or a supplied fingerprint does not match.
	ErrInvalidRange = errors.New("darksafe: invalid audit range")
	// ErrAuditNotFound means no record exists at the requested sequence.
	ErrAuditNotFound = errors.New("darksafe: audit record not found")
	// ErrAuditNotADecision means the record at the sequence is not a
	// decision record and therefore cannot be rechecked.
	ErrAuditNotADecision = errors.New("darksafe: audit record is not a decision")
)

// PolicyChange captures a successful publish or rollback.
type PolicyChange struct {
	// Version is the newly created policy version.
	Version int
	// Policies is the full policy set of the new version.
	Policies []Policy
	// SourceVersion is the version copied by a rollback, and 0 for an
	// ordinary publish.
	SourceVersion int
	// RolledBack reports whether the change was produced by Rollback.
	RolledBack bool
}

// DecisionRecord captures one Decide call: the full request and the
// decision actually returned.
type DecisionRecord struct {
	Request  OrgRequest
	Decision Decision
}

// AuditRecord is one immutable entry in an organization's audit chain.
type AuditRecord struct {
	Org      string
	Seq      int // organization-local, starting at 1 and gapless
	Kind     string
	Change   *PolicyChange   // present when Kind == AuditPolicyChange
	Decision *DecisionRecord // present when Kind == AuditDecision

	// PrevFingerprint is the fingerprint of the preceding record, or the
	// genesis fingerprint for the first record.
	PrevFingerprint string
	// Fingerprint binds this record's full content to its predecessor.
	Fingerprint string
}

// rawEnvelopePrefix opens every raw-byte canonical encoding. It never
// coincides with the start of a JSON envelope (always '{'), so
// fingerprints from the two encodings live in collision-free spaces.
const rawEnvelopePrefix = "darksafe-audit-raw-v1\x00"

// fingerprintTag delimits one field or nested value within the canonical
// binary encoding. Distinct tags keep two payloads that merely share
// adjacent bytes apart (e.g. ["ab",""] vs ["a","b"]).
type fingerprintTag byte

const (
	tagEnvelope fingerprintTag = iota + 1
	tagSeq
	tagString
	tagStringList
	tagBool
	tagPolicy
	tagPolicyList
	tagChange
	tagSubject
	tagResource
	tagDecision
	tagDecisionRecord
)

// fingerprintEncoder builds the canonical byte representation of an
// envelope. Unlike encoding/json it writes string contents byte-for-byte
// with an explicit length prefix, so strings carrying invalid UTF-8 stay
// distinguishable: encoding/json renders both a raw 0xFF byte and a raw
// 0xFE byte as the U+FFFD replacement rune, collapsing genuinely
// different content onto identical fingerprints.
type fingerprintEncoder struct {
	buf []byte
}

func (e *fingerprintEncoder) tag(t fingerprintTag) {
	e.buf = append(e.buf, byte(t))
}

func (e *fingerprintEncoder) int64Tag(t fingerprintTag, v int64) {
	e.tag(t)
	var b [8]byte

// This file holds the shared core of single-decision review. The online
// Store.RecheckDecision and the store-free RecheckDecisionOffline acquire
// their material differently — one reads an organization's live history
// and version snapshots, the other a chain-validated export paired with its
// separately retained checkpoint — but once the recorded request and the
// version it actually used are in hand, both replay the exact same
// judgment. That judgment lives only here so the two entry points can never
// drift on version-zero handling, envelope rejection order, or how a
// historical policy set is evaluated.
package darksafe

// replayStatus reports whether replayRecordedDecision produced a decision
// or why the declared version could not be replayed.
type replayStatus int

const (
	// replayDecided means a Decision was recomputed.
	replayDecided replayStatus = iota
	// replayVersionAbsent means content for the declared version exists
	// nowhere in the reviewer's material.
	replayVersionAbsent
	// replayVersionAfterTarget means the version's content exists, but only
	// in a policy change record positioned after the reviewed decision.
	// Online material never yields this: live version snapshots carry no
	// position relative to audit records.
	replayVersionAfterTarget
)

// versionPolicies is one resolver verdict: either the detached full policy
// set of the requested version, or a status explaining why it is unusable.
type versionPolicies struct {
	policies []Policy
	status   replayStatus
}

// resolveVersionPolicies supplies the full content of a non-zero version
// named by a reviewed decision. Implementations are responsible for
// detaching the returned policies from any state or input material.
type resolveVersionPolicies func(version int) versionPolicies

// replayRecordedDecision re-judges a recorded request against the version
// the record declares it actually used. Later publishes or rollbacks are
// never substituted for that version.
//
// A version-0 record first replays the envelope rejections in their fixed
// order (missing organizations and identifiers, empty action, organization
// mismatch, illegal scope, disabled subject); a request that passes is the
// "organization has no published version" denial.
//
// For a non-zero record the version is resolved before any request rule is
// applied: a missing, or only-later, version is an error the caller turns
// into ErrVersionNotFound and must never be masked by an envelope denial,
// even for a disabled subject. Once the version is in hand, the same
// envelope checks run before policy evaluation, so a rejection reports
// version 0 with no matched policies regardless of what the version
// contains. Evaluation itself is the historical policy set only: deny
// overrides allow, matched identifiers are sorted, resource restrictions
// narrow rather than replace scope matching, and subject roles never stand
// in for an organization policy.
func replayRecordedDecision(org string, req OrgRequest, version int, resolve resolveVersionPolicies) (Decision, replayStatus) {
	if version == 0 {
		// The original evaluation used no published version: replay the
		// envelope rejections exactly, in their recorded order, then the
		// not-yet-published denial.
		if d, ok := checkRequest(org, req); !ok {
			return d, replayDecided
		}
		return Decision{Allowed: false, Reason: "organization has no published version"}, replayDecided
	}
	// Resolve the version first. A request the envelope would reject must
	// not turn a missing or later-only declared version into an ordinary
	// denial.
	resolved := resolve(version)
	if resolved.status != replayDecided {
		return Decision{}, resolved.status
	}
	// The version exists as claimed, but chain integrity does not imply the
	// request was admissible: re-run the same envelope checks the online
	// decision runs before any policy is consulted. A rejection here
	// evaluates no policies, hence version 0 and no matches, even when the
	// version holds a fully matching allow policy.
	if d, ok := checkRequest(org, req); !ok {
		return d, replayDecided
	}
	return evaluate(req, resolved.policies, version), replayDecided
}

